            fn = compiled.function
            packed = compiled.packed_metadata
            stream = _stream_getter(device)
    except Exception:
        launch = None
    return [y.dtype, n, device, launch, grid, block, {}, fn, packed, stream,
            launch is not None]

def _slow(y, out, n):
    if not n:
        return
    device = y.get_device()
    key = (device, y.dtype, n)
    plan = _PLANS.get(key)
    if plan is None:
        plan = _PLANS[key] = _build(y, out, n, device)
